function draw() {
	background (255)
	noFill()
	strokeWeight(1)
	stroke(0)
	// animation
	// calculate the dimension of the square
	// based in a sin function
	dimX = 300
	num = 20
	reduction = dimX / num
	//for loop
	for(let i = 0; i < num; i++){
		rect(posX, posY, 
		(dimX) - (reduction * i))
	}
	text (frameCount, 400, 400)
}
